'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
// Lightweight DOM adapter; tests execute the actual checklist factory and refresh.
class Node{
 constructor(tag){this.tagName=tag.toUpperCase();this.children=[];this.dataset={};this.attributes={};this.open=false;this.hidden=false;this.textContent='';this.className='';this.listeners={};}
 append(...nodes){for(const node of nodes){if(node.parent)node.parent.children=node.parent.children.filter(x=>x!==node);node.parent=this;this.children.push(node);}}
 prepend(...nodes){this.append(...nodes);this.children=[...nodes,...this.children.filter(x=>!nodes.includes(x))];}
 after(node){const p=this.parent,index=p.children.indexOf(this);node.parent=p;p.children.splice(index+1,0,node);}
 replaceChildren(...nodes){for(const node of this.children)node.parent=null;this.children=[];this.append(...nodes);}
 setAttribute(name,value){this.attributes[name]=String(value);}
 addEventListener(name,callback){this.listeners[name]=callback;}
 matches(s){if(s.startsWith('.'))return this.className.split(' ').includes(s.slice(1));if(s.startsWith('[data-')){const key=s.slice(6,-1).replace(/-([a-z])/g,(_,c)=>c.toUpperCase());return Object.hasOwn(this.dataset,key);}return this.tagName.toLowerCase()===s;}
 querySelector(s){for(const child of this.children){if(child.matches(s))return child;const found=child.querySelector(s);if(found)return found;}return null;}
 querySelectorAll(s){return this.children.flatMap(n=>[...(n.matches(s)?[n]:[]),...n.querySelectorAll(s)]);}
}
function setup({resolved=false,cutoff=false}={}){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','warning-details.js','departure.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{},stageByView:{[tasks['q-lilac'].view]:'4'}};if(resolved)state.progress.legacy['q-firestarter']=true;const section=new Node('section'),paper=new Node('article'),tools=new Node('section');paper.className='reading-panel';section.append(paper);c.document={createElement:tag=>new Node(tag),getElementById:id=>id===tasks['departure-review'].view?section:null,querySelector:s=>s==='#whiteorchard-preparation-tools'?tools:null,addEventListener(){}};c.location={hash:cutoff?'#'+tasks['q-lilac'].view+'/4':'#home'};c.addEventListener=()=>{};let queue=[];const medallion={removeWarnings(predicate){queue=queue.filter(x=>!predicate(x));},reconcileWarnings(){queue=queue.filter(w=>w.isValid());},getHistory:()=>[],enqueueWarning(w){queue.push(w);}};const before=JSON.stringify(state),api=w.createPhoenixDeparture({state,tasks,engine,medallion,navigate(){}});return {api,state,paper,tools,before,queue:()=>queue};}
test('real renderer preserves Resolved expansion through refresh and adds shared overlay triggers',()=>{const x=setup({resolved:true}),first=x.paper.querySelector('.departure-resolved');assert.ok(first);first.open=true;x.api.refresh();const second=x.paper.querySelector('.departure-resolved');assert.notEqual(second,first);assert.equal(second.open,true);const titles=x.paper.querySelectorAll('.departure-title');assert.equal(titles.length,4);assert.ok(titles.every(n=>n.tagName==='BUTTON'&&n.dataset.warningDetails));assert.equal(JSON.stringify(x.state),x.before);});
test('real cutoff refresh queues unrecorded risk reminders and removes stale ones after correction',()=>{const x=setup({cutoff:true});assert.equal(x.queue().length,1);assert.match(x.queue()[0].id,/q-firestarter/);assert.match(x.queue()[0].id,/q-missing/);x.api.refresh();assert.equal(x.queue().length,1);x.state.progress.manual.departed=true;x.api.refresh();assert.equal(x.queue().length,0);});
test('real renderer puts regional link in preparation tools and omits optional content',()=>{const x=setup();assert.equal(x.tools.querySelectorAll('a').length,1);assert.equal(x.paper.querySelector('.departure-optional'),null);assert.equal(x.paper.querySelectorAll('.departure-item').length,4);assert.match(x.paper.querySelector('.departure-summary').textContent,/0 known open risks · 4 unknown items/);});
